package com.careerpilot.modules.interview.entity;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="interview_answers")@Getter@Setter@NoArgsConstructor public class InterviewAnswer{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="session_id")private InterviewSession session;@Column(name="sequence_number",nullable=false)private int sequenceNumber;@Column(nullable=false,columnDefinition="TEXT")private String question;@Column(nullable=false,columnDefinition="TEXT")private String transcript;@Column(columnDefinition="TEXT")private String strengths;@Column(name="needs_improvement",columnDefinition="TEXT")private String needsImprovement;@Column(name="next_focus",length=500)private String nextFocus;@Column(name="suggested_answer",columnDefinition="TEXT")private String suggestedAnswer;@Column(name="topics_to_review",columnDefinition="TEXT")private String topicsToReview;@Column(name="technical_correctness",nullable=false)private int technicalCorrectness;@Column(nullable=false)private int relevance;@Column(name="answer_structure",nullable=false)private int answerStructure;@Column(nullable=false)private int completeness;@Column(name="communication_clarity",nullable=false)private int communicationClarity;@Column(name="answer_duration_seconds")private Integer answerDurationSeconds;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}
